(window.EXSUB_C=window.EXSUB_C||{})[6]={"a-2":[{"t":"Art. 2 · Quedan excluidos del ámbito de aplicación de la ley","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Art. 2 · Quedan excluidos del ámbito de aplicación de la ley</div><div class=\"vis-arbol\"><div class=\"vis-raiz\">Quedan <mark class=\"m-personalizado\">excluidos</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\">a) Los <mark class=\"m-personalizado\">agentes diplomáticos y los funcionarios consulares</mark> acreditados en España, así como los demás miembros de las misiones diplomáticas permanentes o especiales y de las oficinas consulares y sus familiares que, en virtud de las normas del Derecho internacional, estén exentos de las obligaciones relativas a su <mark class=\"m-personalizado\">inscripción como extranjeros y a la obtención de la autorización de residencia</mark>.</div><div class=\"vis-rama\">b) Los <mark class=\"m-personalizado\">representantes,</mark> <mark class=\"m-autoridad\">delegados</mark> <mark class=\"m-personalizado\">y demás miembros de las Misiones permanentes o de las Delegaciones</mark> ante los Organismos intergubernamentales con sede en España o en Conferencias internacionales que se celebren en España, así como sus familiares.</div><div class=\"vis-rama\">c) Los <mark class=\"m-personalizado\">funcionarios destinados en Organizaciones internacionales o intergubernamentales</mark> con sede en España, así como sus familiares, a quienes los Tratados en los que sea parte España eximan de las obligaciones mencionadas en el párrafo a) de este artículo.</div></div></div></div>"},{"t":"Art. 2 bis · Principios de la política inmigratoria (todas las Administraciones Públicas)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Art. 2 bis · Principios de la política inmigratoria (todas las Administraciones Públicas)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\">Corresponde al <mark class=\"m-autoridad\">Gobierno</mark> la definición, planificación, regulación y desarrollo de la política de inmigración, <u class=\"m-clave\">sin perjuicio</u> de las competencias de las <mark class=\"m-autoridad\">Comunidades Autónomas y Entidades Locales</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\">a) la coordinación con las políticas definidas por la Unión Europea;</div><div class=\"vis-rama\">b) la ordenación de los flujos migratorios laborales, de acuerdo con las necesidades de la <mark class=\"m-personalizado\">situación nacional del empleo</mark>;</div><div class=\"vis-rama\">c) la integración social de los inmigrantes mediante <mark class=\"m-personalizado\">políticas transversales</mark> dirigidas a toda la ciudadanía;</div><div class=\"vis-rama\">d) la igualdad efectiva entre mujeres y hombres;</div><div class=\"vis-rama\">e) la efectividad del principio de no discriminación y, consecuentemente, el reconocimiento de iguales derechos y obligaciones para todos aquellos que vivan o trabajen legalmente en España, en los términos previstos en la Ley;</div><div class=\"vis-rama\">f) la garantía del ejercicio de los derechos que la Constitución, los tratados internacionales y las leyes reconocen a todas las personas;</div><div class=\"vis-rama\">g) la lucha contra la inmigración irregular y la persecución del tráfico ilícito de personas;</div><div class=\"vis-rama\">h) la persecución de la trata de seres humanos;</div><div class=\"vis-rama\">i) la igualdad de trato en las condiciones laborales y de Seguridad Social;</div><div class=\"vis-rama\">j) la promoción del diálogo y la colaboración con los países de origen y tránsito de inmigración, mediante <mark class=\"m-personalizado\">acuerdos marco</mark> dirigidos a ordenar de manera efectiva los flujos migratorios, así como a fomentar y coordinar las iniciativas de cooperación al desarrollo y codesarrollo.</div><div class=\"vis-rama\">3. El <mark class=\"m-autoridad\">Estado</mark> <mark class=\"m-accion\">garantizará</mark> el <mark class=\"m-personalizado\">principio de solidaridad</mark>, consagrado en la Constitución, atendiendo a las especiales circunstancias de aquellos territorios en los que los flujos migratorios tengan una especial incidencia.</div></div></div></div>"}],"b-4":[{"t":"Art. 4 · Tarjeta de identidad de extranjero","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⏱</i>Art. 4 · Tarjeta de identidad de extranjero</div><div class=\"vis-plazos\"><div class=\"vis-plazo\"><span class=\"n\"><mark class=\"m-plazo\">> 6 meses</mark></span>Todos los extranjeros a los que se haya expedido un visado o una autorización para permanecer en España por un período <mark class=\"m-personalizado\">superior a seis meses</mark>, <mark class=\"m-accion\">obtendrán</mark> la tarjeta de identidad de extranjero.</div><div class=\"vis-plazo\"><span class=\"n\"><mark class=\"m-plazo\">1 mes</mark></span><mark class=\"m-accion\">Deberán solicitarla</mark> <mark class=\"m-personalizado\">personalmente</mark> en el plazo de <mark class=\"m-plazo\">un mes</mark> desde su entrada en España o desde que se conceda la autorización, respectivamente.</div><div class=\"vis-plazo\"><span class=\"n\"><u class=\"m-clave\">Excepción</u></span><mark class=\"m-accion\">Estarán</mark> <u class=\"m-clave\">exceptuados</u> de dicha obligación los titulares de un <mark class=\"m-personalizado\">visado de residencia y trabajo de temporada</mark>.</div><div class=\"vis-plazo\"><span class=\"n\"><mark class=\"m-plazo\">≤ 6 meses</mark></span><mark class=\"m-personalizado\">Reglamentariamente</mark> <mark class=\"m-accion\">se desarrollarán</mark> los supuestos en que <mark class=\"m-accion\">se podrá obtener</mark> dicha tarjeta cuando se haya concedido una autorización para permanecer en España por un periodo no superior a seis meses.</div></div></div>"}],"a-17":[{"t":"Art. 17 · Familiares reagrupables por el extranjero residente","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Art. 17 · Familiares reagrupables por el extranjero residente</div><div class=\"vis-arbol\"><div class=\"vis-raiz\">El extranjero residente tiene derecho a reagrupar con él en España a:</div><div class=\"vis-ramas\"><div class=\"vis-rama\">a) El <mark class=\"m-personalizado\">cónyuge</mark> del residente, siempre que no se encuentre separado de hecho o de derecho, y que el matrimonio no se haya celebrado en fraude de ley. <u class=\"m-clave\">En ningún caso</u> <mark class=\"m-accion\">podrá reagruparse</mark> a <mark class=\"m-personalizado\">más de un cónyuge</mark> aunque la ley personal del extranjero admita esta modalidad matrimonial.</div><div class=\"vis-rama\">b) Los <mark class=\"m-personalizado\">hijos</mark> del residente y del cónyuge, incluidos los adoptados, siempre que sean <mark class=\"m-plazo\">menores de dieciocho años</mark> o personas con discapacidad que no sean objetivamente capaces de proveer a sus propias necesidades debido a su estado de salud.</div><div class=\"vis-rama\">c) Los <mark class=\"m-plazo\">menores de dieciocho años</mark> y los mayores de esa edad que no sean objetivamente capaces de proveer a sus propias necesidades, debido a su estado de salud, cuando el residente extranjero sea su <mark class=\"m-personalizado\">representante legal</mark>.</div><div class=\"vis-rama\">d) Los <mark class=\"m-personalizado\">ascendientes en primer grado</mark> del reagrupante y de su cónyuge cuando estén a su cargo, sean <mark class=\"m-plazo\">mayores de sesenta y cinco años</mark> y existan razones que justifiquen la necesidad de autorizar su residencia en España. <u class=\"m-clave\">Excepcionalmente</u>, cuando concurran <mark class=\"m-personalizado\">razones de carácter humanitario</mark>, <mark class=\"m-accion\">podrá reagruparse</mark> al ascendiente menor de sesenta y cinco años.</div><div class=\"vis-rama\">4. La persona que mantenga con el extranjero residente una <mark class=\"m-personalizado\">relación de afectividad análoga a la conyugal</mark> <mark class=\"m-accion\">se equiparará</mark> al cónyuge. <u class=\"m-clave\">En todo caso</u>, las situaciones de matrimonio y de análoga relación de afectividad <mark class=\"m-accion\">se considerarán</mark> <mark class=\"m-personalizado\">incompatibles</mark> entre sí.</div></div></div></div>"}],"a-23":[{"t":"Art. 23.2 · En cualquier caso, constituyen actos de discriminación","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Art. 23.2 · En cualquier caso, constituyen actos de discriminación</div><div class=\"vis-arbol\"><div class=\"vis-raiz\">Discriminación: acto que, directa o indirectamente, conlleve una distinción, exclusión, restricción o preferencia contra un extranjero basada en la <mark class=\"m-personalizado\">raza, el color, la ascendencia o el origen nacional o étnico, las convicciones y prácticas religiosas</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\">a) Los efectuados por la <mark class=\"m-autoridad\">autoridad</mark> o funcionario público o personal encargado de un servicio público, que en el ejercicio de sus funciones, <mark class=\"m-personalizado\">por acción u omisión</mark>, realice cualquier acto discriminatorio prohibido por la ley.</div><div class=\"vis-rama\">b) Todos los que impongan condiciones más gravosas que a los españoles, o que impliquen <mark class=\"m-personalizado\">resistencia a facilitar</mark> a un extranjero <mark class=\"m-personalizado\">bienes o servicios ofrecidos al público</mark>.</div><div class=\"vis-rama\">c) Todos los que impongan <mark class=\"m-personalizado\">ilegítimamente</mark> condiciones más gravosas que a los españoles o restrinjan o limiten el acceso al trabajo, a la vivienda, a la educación, a la formación profesional y a los servicios sociales y socioasistenciales, al extranjero que se encuentre <mark class=\"m-personalizado\">regularmente</mark> en España.</div><div class=\"vis-rama\">d) Todos los que impidan, a través de acciones u omisiones, el ejercicio de una <mark class=\"m-personalizado\">actividad económica emprendida legítimamente</mark> por un extranjero residente legalmente en España.</div><div class=\"vis-rama\">e) Constituye <mark class=\"m-personalizado\">discriminación indirecta</mark> todo tratamiento derivado de la adopción de criterios que perjudiquen a los trabajadores por su condición de extranjeros o por pertenecer a una determinada raza, religión, etnia o nacionalidad.</div></div></div></div>"}],"a-25":[{"t":"Art. 25 bis · Clases de visado","h":"<div class=\"vis\"><div class=\"vis-t\"><i>▦</i>Art. 25 bis · Clases de visado</div><div class=\"vis-tabla\"><div class=\"vt-cab\"><span>Visado</span><span>Habilita para…</span></div><div class=\"vt-nodo\"><div class=\"vt-et o\">a) Tránsito</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">Transitar por la zona de tránsito internacional de un aeropuerto español o atravesar el territorio español. <u class=\"m-clave\">No</u> <mark class=\"m-accion\">será</mark> exigible en casos de tránsito a efectos de <mark class=\"m-personalizado\">repatriación o alejamiento por vía aérea</mark> solicitado por un <mark class=\"m-autoridad\">Estado</mark> miembro de la UE o por un tercer estado con acuerdo con España.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et v\">b) Estancia</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p o\"><mark class=\"m-plazo\">3 meses / semestre</mark></span><div class=\"vt-t\">Una estancia ininterrumpida o estancias sucesivas por un período o suma de períodos cuya duración total no exceda de tres meses por semestre a partir de la fecha de la primera entrada.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et c\">c) Residencia</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">Residir <u class=\"m-clave\">sin</u> ejercer actividad laboral o profesional.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et o\">d) Residencia y trabajo</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p v\"><mark class=\"m-plazo\">máx. 3 meses</mark></span><div class=\"vt-t\">Entrada y estancia por un período máximo de tres meses y comienzo, en ese plazo, de la actividad; en este tiempo <mark class=\"m-accion\">deberá producirse</mark> el <mark class=\"m-personalizado\">alta en la Seguridad Social</mark>, que <mark class=\"m-accion\">dotará</mark> de eficacia a la autorización.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et v\">e) Residencia y trabajo de temporada</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p n\"><mark class=\"m-plazo\">9 meses / 12</mark></span><div class=\"vt-t\">Trabajar <mark class=\"m-personalizado\">por cuenta ajena</mark> hasta nueve meses en un período de doce meses consecutivos.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et c\">f) Estudios</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">Permanecer en España para cursos, estudios, trabajos de investigación o formación, intercambio de alumnos, prácticas no laborales o servicios de voluntariado, <u class=\"m-clave\">no remunerados laboralmente</u>.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et o\">g) Investigación</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">Permanecer en España para realizar proyectos de investigación en el marco de un <mark class=\"m-personalizado\">convenio de acogida</mark> firmado con un organismo de investigación.</div></div></div></div></div></div>"},{"t":"Art. 25 · Tramitación de urgencia (Ministerio del Interior, de oficio o a petición)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Art. 25 · Tramitación de urgencia (Ministerio del Interior, de oficio o a petición)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\">Plazos del procedimiento ordinario <mark class=\"m-personalizado\">reducidos a la mitad</mark>; se informa a la CIAR</div><div class=\"vis-ramas\"><div class=\"vis-rama\">a) que parezcan manifiestamente fundadas;</div><div class=\"vis-rama\">b) solicitantes con necesidades específicas, especialmente menores no acompañados;</div><div class=\"vis-rama\">c) que planteen exclusivamente cuestiones ajenas a los requisitos;</div><div class=\"vis-rama\">d) solicitante procedente de un país de origen considerado seguro;</div><div class=\"vis-rama\">e) presentada, sin motivo justificado, transcurrido el plazo de <mark class=\"m-plazo\">un mes</mark>;</div><div class=\"vis-rama\">f) solicitante incurso en supuestos de exclusión o denegación.</div><div class=\"vis-rama\">2. Solicitudes en un Centro de Internamiento: régimen de frontera y, si se admiten, urgencia.</div></div></div></div>"}],"b-28":[{"t":"Art. 28.3 · La salida será obligatoria en los siguientes supuestos","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Art. 28.3 · La salida será obligatoria en los siguientes supuestos</div><div class=\"vis-arbol\"><div class=\"vis-raiz\">Salidas <mark class=\"m-personalizado\">libres</mark>, excepto en los casos previstos en el Código Penal y en la Ley; <u class=\"m-clave\">excepcionalmente</u>, el <mark class=\"m-autoridad\">Ministro del Interior</mark> <mark class=\"m-accion\">podrá prohibir</mark> la salida por razones de <mark class=\"m-personalizado\">seguridad nacional o de salud pública</mark> (expedientes <u class=\"m-clave\">siempre</u> de carácter individual)</div><div class=\"vis-ramas\"><div class=\"vis-rama\">a) Expulsión del territorio español por <mark class=\"m-personalizado\">orden judicial</mark>, en los casos previstos en el <mark class=\"m-personalizado\">Código Penal</mark>.</div><div class=\"vis-rama\">b) Expulsión o devolución acordadas por <mark class=\"m-personalizado\">resolución administrativa</mark> en los casos previstos en la presente Ley.</div><div class=\"vis-rama\">c) <mark class=\"m-personalizado\">Denegación administrativa</mark> de las solicitudes formuladas por el extranjero para continuar permaneciendo en territorio español, o falta de autorización para encontrarse en España.</div><div class=\"vis-rama\">d) Cumplimiento del plazo en el que un <mark class=\"m-personalizado\">trabajador</mark> extranjero se hubiera comprometido a regresar a su país de origen en el marco de un programa de <mark class=\"m-personalizado\">retorno voluntario</mark>.</div></div></div></div>"}],"a-30":[{"t":"Art. 30 · Situación de estancia","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⏱</i>Art. 30 · Situación de estancia</div><div class=\"vis-plazos\"><div class=\"vis-plazo\"><span class=\"n\"><mark class=\"m-plazo\">≤ 90 días</mark></span>Estancia es la permanencia en territorio español por un período de tiempo <mark class=\"m-personalizado\">no superior a 90 días</mark>, <u class=\"m-clave\">sin perjuicio</u> del régimen de estudios, intercambio de alumnos, prácticas no laborales o voluntariado.</div><div class=\"vis-plazo\"><span class=\"n\"><mark class=\"m-plazo\">Después</mark></span>Transcurrido dicho tiempo, <mark class=\"m-accion\">será</mark> preciso obtener o una <mark class=\"m-personalizado\">prórroga de estancia</mark> o una <mark class=\"m-personalizado\">autorización de residencia</mark>.</div><div class=\"vis-plazo\"><span class=\"n\"><mark class=\"m-plazo\">3 meses / 6</mark></span>Entrada <mark class=\"m-personalizado\">con visado</mark> de duración inferior a tres meses: <mark class=\"m-accion\">se podrá prorrogar</mark> la estancia, que <u class=\"m-clave\">en ningún caso</u> <mark class=\"m-accion\">podrá</mark> ser superior a tres meses, en un período de seis meses.</div><div class=\"vis-plazo\"><span class=\"n\"><mark class=\"m-plazo\">> 3 meses</mark></span>Entrada <mark class=\"m-personalizado\">sin visado</mark>: cuando concurran <mark class=\"m-personalizado\">circunstancias excepcionales</mark> que lo justifiquen, <mark class=\"m-accion\">podrá autorizarse</mark> la estancia más allá de tres meses.</div></div></div>"}],"b-38":[{"t":"Art. 38.6 · La autorización de residencia y trabajo se renovará a su expiración","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Art. 38.6 · La autorización de residencia y trabajo se renovará a su expiración</div><div class=\"vis-arbol\"><div class=\"vis-raiz\">Concesión inicial: <mark class=\"m-accion\">se tendrá</mark> en cuenta la <mark class=\"m-personalizado\">situación nacional de empleo</mark> (Catálogo de Ocupaciones de Difícil Cobertura, previa consulta de la <mark class=\"m-autoridad\">Comisión Laboral Tripartita de Inmigración</mark>); limitada a un determinado <mark class=\"m-personalizado\">territorio y ocupación</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\">a) Cuando persista o se renueve el contrato de trabajo que motivó su concesión inicial, o cuando se cuente con un nuevo contrato.</div><div class=\"vis-rama\">b) Cuando por la <mark class=\"m-autoridad\">autoridad</mark> competente, conforme a la normativa de la Seguridad Social, se hubiera otorgado una <mark class=\"m-personalizado\">prestación contributiva por desempleo</mark>.</div><div class=\"vis-rama\">c) Cuando el extranjero sea beneficiario de una <mark class=\"m-personalizado\">prestación económica asistencial de carácter público</mark> destinada a lograr su inserción social o laboral.</div><div class=\"vis-rama\">d) Cuando concurran otras circunstancias previstas reglamentariamente, en particular, los supuestos de extinción del contrato de trabajo o suspensión de la relación laboral como consecuencia de ser <mark class=\"m-personalizado\">víctima de violencia de género</mark>.</div><div class=\"vis-rama\">7. A partir de la primera concesión, las autorizaciones <mark class=\"m-accion\">se concederán</mark> <u class=\"m-clave\">sin limitación alguna</u> de ámbito geográfico u ocupación.</div></div></div></div>"}],"a-40":[{"t":"Art. 40.1 · No se tendrá en cuenta la situación nacional de empleo cuando el contrato vaya dirigido a","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Art. 40.1 · No se tendrá en cuenta la situación nacional de empleo cuando el contrato vaya dirigido a</div><div class=\"vis-arbol\"><div class=\"vis-raiz\">Exención de la situación nacional de empleo</div><div class=\"vis-ramas\"><div class=\"vis-rama\">a) Familiares reagrupados en edad laboral, cónyuge o hijo de extranjero residente con autorización renovada, e hijo de español nacionalizado o de ciudadanos de la UE / EEE que lleven <mark class=\"m-plazo\">como mínimo, un año</mark> residiendo legalmente.</div><div class=\"vis-rama\">b) Los titulares de una autorización previa de trabajo que pretendan su renovación.</div><div class=\"vis-rama\">c) Los trabajadores necesarios para el montaje por renovación de una instalación o equipos productivos.</div><div class=\"vis-rama\">d) Los que hubieran gozado de la condición de refugiados, durante <mark class=\"m-plazo\">el año siguiente</mark> a la cesación de la aplicación de la Convención de Ginebra.</div><div class=\"vis-rama\">e) Los reconocidos como apátridas y los que hubieran perdido la condición de apátridas <mark class=\"m-plazo\">el año siguiente</mark> a la terminación de dicho estatuto.</div><div class=\"vis-rama\">f) Los extranjeros que tengan a su cargo ascendientes o descendientes de nacionalidad española.</div><div class=\"vis-rama\">g) Los extranjeros <mark class=\"m-personalizado\">nacidos y residentes</mark> en España.</div><div class=\"vis-rama\">h) Los hijos o nietos de español <mark class=\"m-personalizado\">de origen</mark>.</div><div class=\"vis-rama\">i) Los menores extranjeros en edad laboral con autorización de residencia tutelados por la entidad de protección de menores, una vez acreditada la imposibilidad de retorno.</div><div class=\"vis-rama\">j) Los que obtengan la autorización por circunstancias excepcionales y, en todo caso, las víctimas de violencia de género o de trata de seres humanos.</div><div class=\"vis-rama\">k) Los titulares de autorizaciones de trabajo de temporada durante <mark class=\"m-plazo\">dos años naturales</mark> que hayan retornado a su país.</div><div class=\"vis-rama\">l) Los que hayan renunciado a su autorización de residencia y trabajo en virtud de un programa de retorno voluntario.</div><div class=\"vis-rama\">2. Tampoco: puestos de confianza y directivos; profesionales altamente cualificados; trabajadores en plantilla de una empresa o grupo en otro país; artistas de reconocido prestigio.</div></div></div></div>"},{"t":"Art. 40 · Extensión familiar (tramita la OAR, estudia la CIAR, resuelve el Ministro del Interior)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Art. 40 · Extensión familiar (tramita la OAR, estudia la CIAR, resuelve el Ministro del Interior)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\">Restablecimiento de la unidad familiar por extensión</div><div class=\"vis-ramas\"><div class=\"vis-rama\">a) Ascendientes en primer grado que acrediten la <mark class=\"m-personalizado\">dependencia</mark> y descendientes en primer grado <mark class=\"m-personalizado\">menores de edad</mark> (excepto distinta nacionalidad; pruebas científicas si hay dudas).</div><div class=\"vis-rama\">b) Cónyuge o persona ligada por análoga relación, salvo divorcio, separación legal o de hecho, distinta nacionalidad o estatuto por razón de género con persecución por el cónyuge o conviviente.</div><div class=\"vis-rama\">c) Otro adulto responsable del beneficiario cuando éste sea un <mark class=\"m-personalizado\">menor no casado</mark>.</div><div class=\"vis-rama\">d) Otros miembros de la familia con dependencia y convivencia previa en el país de origen.</div><div class=\"vis-rama\">4. <u class=\"m-clave\">En ningún caso</u> a personas incursas en causas de exclusión o denegación.</div></div></div></div>"}],"a-41":[{"t":"Art. 41 · No será necesaria la obtención de autorización de trabajo para","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Art. 41 · No será necesaria la obtención de autorización de trabajo para</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><u class=\"m-clave\">No</u> necesitan autorización de trabajo</div><div class=\"vis-ramas\"><div class=\"vis-rama\">a) Técnicos y científicos extranjeros, invitados o contratados por el <mark class=\"m-autoridad\">Estado,</mark> las comunidades autónomas, los entes locales o los organismos de investigación promovidos o participados mayoritariamente por éstos.</div><div class=\"vis-rama\">b) Los profesores extranjeros invitados o contratados por una <mark class=\"m-personalizado\">universidad española</mark>.</div><div class=\"vis-rama\">c) Personal directivo y profesorado de instituciones culturales y docentes dependientes de otros <mark class=\"m-autoridad\">Estados,</mark> o privadas, de acreditado prestigio, en tanto limiten su actividad a la ejecución de tales programas.</div><div class=\"vis-rama\">d) Funcionarios civiles o militares de Administraciones estatales extranjeras que vengan a desarrollar actividades en virtud de acuerdos de cooperación con la Administración española.</div><div class=\"vis-rama\">e) Corresponsales de medios de comunicación social extranjeros, <mark class=\"m-personalizado\">debidamente acreditados</mark>.</div><div class=\"vis-rama\">f) Miembros de misiones científicas internacionales, <mark class=\"m-personalizado\">autorizados por el</mark> <mark class=\"m-autoridad\">Estado</mark>.</div><div class=\"vis-rama\">g) Artistas que vengan a realizar actuaciones concretas que <u class=\"m-clave\">no</u> supongan una actividad continuada.</div><div class=\"vis-rama\">h) <mark class=\"m-autoridad\">Ministros,</mark> religiosos o representantes de iglesias y confesiones <mark class=\"m-personalizado\">inscritas</mark>, en tanto limiten su actividad a funciones <mark class=\"m-personalizado\">estrictamente religiosas</mark>.</div><div class=\"vis-rama\">i) Miembros de los <mark class=\"m-autoridad\">órganos</mark> de representación de <mark class=\"m-personalizado\">sindicatos</mark> homologados internacionalmente, limitados a funciones estrictamente sindicales.</div><div class=\"vis-rama\">j) Menores extranjeros en edad laboral tutelados, para actividades que favorezcan su integración social.</div></div></div></div>"}],"b-48":[{"t":"Art. 48.3 · Elementos y criterios esenciales de cuantificación (solo modificables por norma del mismo rango)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Art. 48.3 · Elementos y criterios esenciales de cuantificación (solo modificables por norma del mismo rango)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\">Importe por <mark class=\"m-personalizado\">Orden ministerial</mark>; las normas que lo fijen irán acompañadas de una <mark class=\"m-personalizado\">memoria económico-financiera</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\">a) Visado: gastos administrativos de tramitación, limitación de efectos del visado de tránsito aeroportuario, duración de la estancia, número de entradas, carácter de la residencia y, en su caso, expedición en frontera.</div><div class=\"vis-rama\">b) Prórroga de estancia: la duración de la prórroga.</div><div class=\"vis-rama\">c) Autorizaciones de residencia: duración, carácter definitivo o temporal y, dentro de estas, primera o ulteriores concesiones o renovaciones.</div><div class=\"vis-rama\">d) Autorizaciones de trabajo: duración, extensión y ámbito, carácter y modalidades de la relación por cuenta ajena y, en su caso, importe del salario pactado.</div><div class=\"vis-rama\">e) Tarjetas de identidad de extranjeros: duración de la autorización y primera o ulteriores concesiones o renovaciones; en todo caso, carácter individual o colectivo.</div><div class=\"vis-rama\">4. Visados: <mark class=\"m-accion\">se adecuarán</mark> al <mark class=\"m-personalizado\">derecho comunitario</mark> y <mark class=\"m-accion\">se acomodarán</mark> al <mark class=\"m-personalizado\">principio de reciprocidad</mark>.</div></div></div></div>"}],"a-52":[{"t":"Art. 52 · Infracciones LEVES (multa de hasta 500 euros)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Art. 52 · Infracciones LEVES (multa de hasta 500 euros)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\">Son infracciones <mark class=\"m-personalizado\">leves</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\">a) La omisión o el retraso en la comunicación de los cambios de nacionalidad, de estado civil o de domicilio, y de otras circunstancias determinantes de su situación laboral.</div><div class=\"vis-rama\">b) El retraso, <mark class=\"m-plazo\">hasta tres meses</mark>, en la solicitud de renovación de las autorizaciones una vez hayan caducado.</div><div class=\"vis-rama\">c) Encontrarse trabajando sin haber solicitado autorización para trabajar <mark class=\"m-personalizado\">por cuenta propia</mark>, cuando se cuente con autorización de residencia temporal.</div><div class=\"vis-rama\">d) Encontrarse trabajando en una ocupación, sector de actividad o ámbito geográfico no contemplado por la autorización de la que se es titular.</div><div class=\"vis-rama\">e) La contratación de trabajadores cuya autorización no les habilita para esa ocupación o ámbito geográfico (una infracción por cada trabajador).</div><div class=\"vis-rama\">f) La ausencia de comunicación, por las entidades de atención a menores extranjeros no acompañados, de la localización de estos menores.</div></div></div></div>"}],"a-53":[{"t":"Art. 53 · Infracciones GRAVES (multa de 501 hasta 10.000 euros)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Art. 53 · Infracciones GRAVES (multa de 501 hasta 10.000 euros)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\">Son infracciones <mark class=\"m-personalizado\">graves</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\">1.a) Encontrarse <mark class=\"m-personalizado\">irregularmente</mark> en territorio español (sin prórroga de estancia, sin autorización de residencia o con ella caducada <mark class=\"m-plazo\">más de tres meses</mark> sin haber solicitado la renovación).</div><div class=\"vis-rama\">1.b) Encontrarse trabajando sin autorización de trabajo, cuando <u class=\"m-clave\">no</u> cuente con autorización de residencia válida.</div><div class=\"vis-rama\">1.c) Ocultación dolosa o falsedad grave en la comunicación de cambios de nacionalidad, estado civil o domicilio, o en el alta en el padrón, siempre que no constituyan delito.</div><div class=\"vis-rama\">1.d) El incumplimiento de las medidas impuestas por razón de seguridad pública, de presentación periódica o de alejamiento de fronteras o núcleos de población.</div><div class=\"vis-rama\">1.e) La <mark class=\"m-autoridad\">comisión</mark> de una <mark class=\"m-personalizado\">tercera infracción leve</mark>, si en <mark class=\"m-plazo\">un año</mark> hubiera sido sancionado por dos faltas leves de la misma naturaleza.</div><div class=\"vis-rama\">1.f) La participación en actividades contrarias al orden público previstas como graves en la LO de Protección de la Seguridad Ciudadana.</div><div class=\"vis-rama\">1.g) Las salidas del territorio por puestos no habilitados, sin exhibir la documentación o contraviniendo las prohibiciones.</div><div class=\"vis-rama\">1.h) Incumplir la obligación de solicitar la tarjeta de identidad de extranjero.</div><div class=\"vis-rama\">2.a) No dar de alta en la Seguridad Social al trabajador cuya autorización se solicitó, o no registrar el contrato (exento el empresario que comunique razones sobrevenidas).</div><div class=\"vis-rama\">2.b) Contraer matrimonio, simular relación afectiva o constituirse en representante legal de un menor con ánimo de lucro o para obtener indebidamente un derecho de residencia.</div><div class=\"vis-rama\">2.c) Promover la permanencia irregular de un extranjero cuya entrada legal contó con una invitación expresa del infractor y continúe a su cargo.</div><div class=\"vis-rama\">2.d) Consentir la inscripción en el Padrón en una vivienda que no sea el domicilio real del extranjero (<mark class=\"m-personalizado\">una infracción por cada persona</mark>).</div></div></div></div>"}],"a-54":[{"t":"Art. 54 · Infracciones MUY GRAVES (multa desde 10.001 hasta 100.000 euros)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Art. 54 · Infracciones MUY GRAVES (multa desde 10.001 hasta 100.000 euros)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\">Son infracciones <mark class=\"m-personalizado\">muy graves</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\">1.a) Participar en actividades contrarias a la seguridad nacional o que puedan perjudicar las relaciones de España con otros países, o actividades contrarias al orden público previstas como muy graves.</div><div class=\"vis-rama\">1.b) Inducir, promover, favorecer o facilitar <mark class=\"m-personalizado\">con ánimo de lucro</mark> la inmigración clandestina, siempre que el hecho <u class=\"m-clave\">no</u> constituya delito.</div><div class=\"vis-rama\">1.c) La realización de conductas de discriminación por motivos raciales, étnicos, nacionales o religiosos, siempre que no constituya delito.</div><div class=\"vis-rama\">1.d) La contratación de trabajadores extranjeros <u class=\"m-clave\">sin</u> haber obtenido con carácter previo la autorización de residencia y trabajo (una infracción por cada trabajador).</div><div class=\"vis-rama\">1.e) Realizar, <mark class=\"m-personalizado\">con ánimo de lucro</mark>, la infracción de consentir la inscripción indebida en el Padrón.</div><div class=\"vis-rama\">1.f) Simular la relación laboral con un extranjero, con ánimo de lucro o para obtener indebidamente derechos.</div><div class=\"vis-rama\">1.g) La <mark class=\"m-autoridad\">comisión</mark> de una <mark class=\"m-personalizado\">tercera infracción grave</mark>, si en <mark class=\"m-plazo\">un año</mark> hubiera sido sancionado por dos faltas graves de la misma naturaleza.</div><div class=\"vis-rama\">2.a) El incumplimiento de las obligaciones de los transportistas de remitir información.</div><div class=\"vis-rama\">2.b) El transporte de extranjeros sin comprobar la validez y vigencia de pasaportes, títulos de viaje o documentos de identidad y, en su caso, del visado.</div><div class=\"vis-rama\">2.c) El incumplimiento de la obligación de los transportistas de hacerse cargo sin pérdida de tiempo del extranjero no autorizado a entrar.</div><div class=\"vis-rama\">3. <u class=\"m-clave\">No</u> es infracción transportar a la frontera a quien, habiendo presentado sin demora su solicitud de protección internacional, la vea <mark class=\"m-personalizado\">admitida a trámite</mark>.</div></div></div></div>"}],"a-56":[{"t":"Art. 56 · Prescripción","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>Art. 56 · Prescripción</div><div class=\"vis-comp\" style=\"--n:3\"><div class=\"vis-col\"><h5>INFRACCIONES</h5><ul><li>Muy graves: <mark class=\"m-plazo\">3 años</mark></li><li>Graves: <mark class=\"m-plazo\">2 años</mark></li><li>Leves: <mark class=\"m-plazo\">6 meses</mark></li></ul></div><div class=\"vis-col\"><h5>SANCIONES</h5><ul><li>Muy graves: <mark class=\"m-plazo\">5 años</mark></li><li>Graves: <mark class=\"m-plazo\">2 años</mark></li><li>Leves: <mark class=\"m-plazo\">1 año</mark></li></ul></div><div class=\"vis-col\"><h5>EXPULSIÓN</h5><ul><li>La prescripción <u class=\"m-clave\">no</u> <mark class=\"m-accion\">empezará</mark> a contar hasta que haya transcurrido el período de prohibición de entrada fijado en la resolución, con un máximo de <mark class=\"m-plazo\">diez años</mark>.</li></ul></div></div></div>"}],"a-58":[{"t":"Art. 58 · Prohibición de entrada y devolución","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⏱</i>Art. 58 · Prohibición de entrada y devolución</div><div class=\"vis-plazos\"><div class=\"vis-plazo\"><span class=\"n\"><mark class=\"m-plazo\">≤ 5 años</mark></span>La expulsión <mark class=\"m-accion\">llevará</mark> consigo la prohibición de entrada; su vigencia <u class=\"m-clave\">no</u> <mark class=\"m-accion\">excederá</mark> de cinco años.</div><div class=\"vis-plazo\"><span class=\"n\"><mark class=\"m-plazo\">≤ 10 años</mark></span><u class=\"m-clave\">Excepcionalmente</u>, amenaza grave para el orden público, la seguridad pública, la seguridad nacional o la salud pública.</div><div class=\"vis-plazo\"><span class=\"n\"><mark class=\"m-personalizado\">Sin expediente</mark></span>Devolución: a) los que, habiendo sido expulsados, contravengan la prohibición de entrada; b) los que pretendan entrar ilegalmente en el país.</div><div class=\"vis-plazo\"><span class=\"n\"><mark class=\"m-personalizado\">Asilo</mark></span>Si se formaliza una solicitud de protección internacional, <u class=\"m-clave\">no</u> <mark class=\"m-accion\">podrá devolverse</mark> hasta que se haya decidido su inadmisión a trámite; tampoco a mujeres embarazadas con riesgo.</div><div class=\"vis-plazo\"><span class=\"n\"><mark class=\"m-plazo\">72 horas</mark></span>Si la devolución no se pudiera ejecutar en este plazo, <mark class=\"m-accion\">se solicitará</mark> de la <mark class=\"m-autoridad\">autoridad judicial</mark> el internamiento.</div><div class=\"vis-plazo\"><span class=\"n\"><mark class=\"m-plazo\">≤ 3 años</mark></span>Devolución por pretender entrar ilegalmente: prohibición de entrada por un plazo máximo de tres años (en el caso a), se reinicia el cómputo de la expulsión quebrantada).</div></div></div>"}],"a-62":[{"t":"Art. 62 · Internamiento","h":"<div class=\"vis\"><div class=\"vis-t\"><i>➜</i>Art. 62 · Internamiento</div><div class=\"vis-flujo\"><div class=\"vis-paso \"><span class=\"et\">Solicitud</span>El <mark class=\"m-autoridad\">instructor</mark> solicita al <mark class=\"m-autoridad\">Juez de Instrucción</mark> competente el ingreso, en expedientes por 54.1.a) y b), 53.1.a), d) y f) y 57.2.</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">Auto</span>El <mark class=\"m-autoridad\">Juez,</mark> previa <mark class=\"m-autoridad\">audiencia</mark> del <mark class=\"m-personalizado\">interesado</mark> y del <mark class=\"m-autoridad\">Ministerio Fiscal</mark>, resuelve por auto motivado (proporcionalidad, riesgo de incomparecencia, actuaciones para evitar la expulsión, condenas previas; enfermedad grave).</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\"><mark class=\"m-plazo\">máx. 60 días</mark></span>Tiempo imprescindible; <u class=\"m-clave\">sin</u> que pueda acordarse un nuevo internamiento por cualquiera de las causas previstas en un mismo expediente.</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">Libertad</span>Si dejan de cumplirse las condiciones, la <mark class=\"m-autoridad\">autoridad</mark> administrativa lo pone inmediatamente en libertad y lo comunica al <mark class=\"m-autoridad\">Juez.</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\"><u class=\"m-clave\">Menores</u></span><mark class=\"m-accion\">No podrá acordarse</mark> el ingreso de menores; los no acompañados se ponen a disposición de las entidades de protección de menores.</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">Comunicación</span>Incoación, detención, internamiento y resolución final se comunican al <mark class=\"m-autoridad\">Ministerio de Asuntos Exteriores</mark> y a la embajada o consulado.</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">Juez</span>Autoriza: <mark class=\"m-autoridad\">Juez</mark> de Instrucción del lugar de la detención. Controla la estancia: <mark class=\"m-autoridad\">Juez</mark> de Instrucción del lugar donde esté el centro (sin ulterior recurso).</div></div></div>"},{"t":"Art. 62 ter · Deberes de los extranjeros internados","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Art. 62 ter · Deberes de los extranjeros internados</div><div class=\"vis-arbol\"><div class=\"vis-raiz\">El extranjero sometido a internamiento <mark class=\"m-accion\">estará</mark> obligado:</div><div class=\"vis-ramas\"><div class=\"vis-rama\">a) A permanecer en el centro a disposición del <mark class=\"m-autoridad\">Juez de Instrucción</mark> que hubiere autorizado su ingreso.</div><div class=\"vis-rama\">b) A observar las normas por las que se rige el centro y cumplir las instrucciones de la dirección y de los funcionarios, así como las relativas a su propio aseo e higiene y la limpieza del centro.</div><div class=\"vis-rama\">c) A mantener una actividad cívica correcta y de respeto con los funcionarios, empleados, visitantes y otros internados.</div><div class=\"vis-rama\">d) A conservar el buen estado de las instalaciones materiales, mobiliario y demás efectos del centro.</div><div class=\"vis-rama\">e) A someterse a <mark class=\"m-personalizado\">reconocimiento médico</mark> a la entrada y salida del centro, y cuando lo disponga el <mark class=\"m-autoridad\">director</mark> por razones de salud colectiva.</div></div></div></div>"}],"a-63":[{"t":"Art. 63 · Procedimiento preferente de expulsión","h":"<div class=\"vis\"><div class=\"vis-t\"><i>➜</i>Art. 63 · Procedimiento preferente de expulsión</div><div class=\"vis-flujo\"><div class=\"vis-paso \"><span class=\"et\">Supuestos</span>53.1.d), 53.1.f), 54.1.a), 54.1.b) y 57.2; y estancia irregular con riesgo de incomparecencia, evitación de la expulsión o riesgo para el orden público o la seguridad (<u class=\"m-clave\">sin</u> período de salida voluntaria).</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">Garantías</span>Asistencia letrada (de oficio, en su caso) e intérprete, gratuitos si carece de medios.</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\"><mark class=\"m-plazo\">48 horas</mark></span>Alegaciones tras el traslado del acuerdo de iniciación motivado y por escrito.</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\"><mark class=\"m-plazo\">3 días</mark></span>Prueba, si se estima; si no hay alegaciones ni prueba, el acuerdo de iniciación vale como propuesta de resolución.</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">Ejecución</span>De forma <mark class=\"m-personalizado\">inmediata</mark>.</div></div></div>"},{"t":"Art. 63 bis · Procedimiento ordinario de expulsión","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⏱</i>Art. 63 bis · Procedimiento ordinario de expulsión</div><div class=\"vis-plazos\"><div class=\"vis-plazo\"><span class=\"n\"><mark class=\"m-personalizado\">Supuestos</mark></span>Los distintos de los del procedimiento preferente.</div><div class=\"vis-plazo\"><span class=\"n\"><mark class=\"m-plazo\">7 – 30 días</mark></span>Plazo de <mark class=\"m-personalizado\">cumplimiento voluntario</mark> desde la notificación; prorrogable por un tiempo prudencial (duración de la estancia, niños escolarizados, vínculos familiares y sociales).</div><div class=\"vis-plazo\"><span class=\"n\"><u class=\"m-clave\">Sin internamiento</u></span>Pueden adoptarse medidas cautelares del art. 61, <u class=\"m-clave\">excepto</u> el internamiento.</div></div></div>"}],"a-64":[{"t":"Art. 64.2 · Garantías durante la prórroga, aplazamiento o suspensión de la expulsión","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Art. 64.2 · Garantías durante la prórroga, aplazamiento o suspensión de la expulsión</div><div class=\"vis-arbol\"><div class=\"vis-raiz\">Expirado el plazo voluntario: detención y conducción; si no se ejecuta en <mark class=\"m-plazo\">72 horas</mark>, internamiento (máx. del art. 62)</div><div class=\"vis-ramas\"><div class=\"vis-rama\">a) El mantenimiento de la unidad familiar con los miembros que se hallen en territorio español.</div><div class=\"vis-rama\">b) La prestación de atención sanitaria de urgencia y tratamiento básico de enfermedades.</div><div class=\"vis-rama\">c) El acceso para los menores, en función de la duración de su estancia, al sistema de enseñanza básica.</div><div class=\"vis-rama\">d) Las necesidades especiales de personas vulnerables.</div><div class=\"vis-rama\">3. Costes: a cargo del <mark class=\"m-personalizado\">empleador</mark> sancionado por 53.2.a) o 54.1.d); en el resto, del extranjero si tuviere medios.</div><div class=\"vis-rama\">5. Se <mark class=\"m-personalizado\">suspende</mark> la ejecución si se formaliza una petición de protección internacional, hasta su inadmisión o resolución.</div></div></div></div>"}],"a-35":[{"t":"Art. 35 ter.2 · Criterios de ubicación de menores no acompañados (sin acuerdo unánime)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⏱</i>Art. 35 ter.2 · Criterios de ubicación de menores no acompañados (sin acuerdo unánime)</div><div class=\"vis-plazos\"><div class=\"vis-plazo\"><span class=\"n\"><mark class=\"m-plazo\">50 %</mark></span>Población de las comunidades o ciudades autónomas de acogida (Estadística continua de población).</div><div class=\"vis-plazo\"><span class=\"n\"><mark class=\"m-plazo\">13 %</mark></span>Renta disponible bruta per cápita de los hogares.</div><div class=\"vis-plazo\"><span class=\"n\"><mark class=\"m-plazo\">15 %</mark></span>En razón inversa a la Tasa de paro (EPA del último cuatrimestre).</div><div class=\"vis-plazo\"><span class=\"n\"><mark class=\"m-plazo\">6 %</mark></span>Esfuerzo en atención a menores no acompañados (promedio de los últimos seis meses; ratio por cada 100.000 habitantes).</div><div class=\"vis-plazo\"><span class=\"n\"><mark class=\"m-plazo\">10 %</mark></span>En razón inversa al dimensionamiento estructural de plazas de acogida (una plaza por cada 2.500 habitantes).</div><div class=\"vis-plazo\"><span class=\"n\"><mark class=\"m-plazo\">2 %</mark></span>Ciudad fronteriza: ponderación negativa del -100 % a la Ciudad de Melilla.</div><div class=\"vis-plazo\"><span class=\"n\"><mark class=\"m-plazo\">2 %</mark></span>Insularidad: ponderación negativa del -100 % a Islas Baleares.</div><div class=\"vis-plazo\"><span class=\"n\"><mark class=\"m-plazo\">2 %</mark></span>Dispersión de la población.</div></div></div>"},{"t":"Arts. 35 bis y 35 quáter · Contingencia migratoria extraordinaria: plazos","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⏱</i>Arts. 35 bis y 35 quáter · Contingencia migratoria extraordinaria: plazos</div><div class=\"vis-plazos\"><div class=\"vis-plazo\"><span class=\"n\"><mark class=\"m-plazo\">× 3</mark></span>Se declara cuando la ocupación del sistema de protección exceda tres veces su capacidad ordinaria.</div><div class=\"vis-plazo\"><span class=\"n\"><mark class=\"m-plazo\">5 días naturales</mark></span>Plazo máximo para aprobar la declaración desde la comunicación de la comunidad o ciudad autónoma afectada.</div><div class=\"vis-plazo\"><span class=\"n\"><mark class=\"m-plazo\">24 horas</mark></span>Inscripción en el Registro de Menores Extranjeros No Acompañados desde la reseña.</div><div class=\"vis-plazo\"><span class=\"n\"><mark class=\"m-plazo\">15 días naturales</mark></span>Traslado a la comunidad de destino y resolución de ubicación y traslado, desde la inscripción en el Registro (oídos el menor y la comunidad de destino, con conocimiento del <mark class=\"m-autoridad\">Ministerio Fiscal).</mark></div></div></div>"}],"b-6":[{"t":"Art. 6.2 · Formas que pueden revestir los actos de persecución (entre otras)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Art. 6.2 · Formas que pueden revestir los actos de persecución (entre otras)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\">Actos <mark class=\"m-personalizado\">suficientemente graves</mark> por su naturaleza o carácter reiterado, o <mark class=\"m-personalizado\">acumulación</mark> suficientemente grave de varias medidas</div><div class=\"vis-ramas\"><div class=\"vis-rama\">a) actos de violencia física o psíquica, incluidos los actos de violencia sexual;</div><div class=\"vis-rama\">b) medidas legislativas, administrativas, policiales o judiciales que sean discriminatorias en sí mismas o que se apliquen de manera discriminatoria;</div><div class=\"vis-rama\">c) procesamientos o penas que sean desproporcionados o discriminatorios;</div><div class=\"vis-rama\">d) denegación de tutela judicial de la que se deriven penas desproporcionadas o discriminatorias;</div><div class=\"vis-rama\">e) procesamientos o penas por la negativa a prestar servicio militar en un conflicto en el que el cumplimiento de dicho servicio conllevaría delitos o actos comprendidos en las cláusulas de exclusión;</div><div class=\"vis-rama\">f) actos de naturaleza sexual que afecten a adultos o a niños.</div></div></div></div>"}],"a-7":[{"t":"Art. 7 · Motivos de persecución","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Art. 7 · Motivos de persecución</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-accion\">Será</mark> <mark class=\"m-personalizado\">indiferente</mark> que posea realmente la característica, a condición de que el agente de persecución <mark class=\"m-personalizado\">se la atribuya</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\">a) Raza: en particular, el <mark class=\"m-personalizado\">color, el origen o la pertenencia a un determinado grupo étnico</mark>.</div><div class=\"vis-rama\">b) Religión: creencias <mark class=\"m-personalizado\">teístas, no teístas y ateas</mark>, la participación o la abstención en cultos formales en privado o en público.</div><div class=\"vis-rama\">c) Nacionalidad: no se limita a poseer o no la ciudadanía; incluye la identidad cultural, étnica o lingüística, los orígenes geográficos o políticos comunes o la relación con la población de otro <mark class=\"m-autoridad\">Estado.</mark></div><div class=\"vis-rama\">d) Opiniones políticas: ideas o creencias sobre los agentes de persecución, <mark class=\"m-personalizado\">independientemente</mark> de que se haya obrado de acuerdo con ellas.</div><div class=\"vis-rama\">e) Grupo social determinado: característica innata o antecedentes comunes que no pueden cambiarse, e identidad diferenciada; incluye orientación sexual o identidad sexual, y, o, edad, y la persecución por motivos de género.</div></div></div></div>"}],"b-8":[{"t":"Arts. 8, 9, 11 y 12 · Exclusión y denegación (asilo / protección subsidiaria)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>Arts. 8, 9, 11 y 12 · Exclusión y denegación (asilo / protección subsidiaria)</div><div class=\"vis-comp\" style=\"--n:3\"><div class=\"vis-col\"><h5>EXCLUSIÓN DEL REFUGIADO (art. 8)</h5><ul><li>Protección o asistencia de un <mark class=\"m-autoridad\">órgano</mark> de las Naciones Unidas distinto del ACNUR (si cesa sin solución: «ipso facto» derecho al asilo).</li><li>Derechos y obligaciones inherentes a la nacionalidad del país de residencia.</li><li>Delitos contra la paz, de guerra o contra la humanidad.</li><li>Delito grave fuera del país de refugio antes de ser admitidas como refugiadas.</li><li>Actos contrarios a las finalidades y principios de las Naciones Unidas.</li><li>También a quienes inciten o participen.</li></ul></div><div class=\"vis-col\"><h5>EXCLUSIÓN DE LA SUBSIDIARIA (art. 11)</h5><ul><li>Delitos contra la paz, de guerra o contra la humanidad.</li><li>Delito grave fuera del país de protección.</li><li>Actos contrarios a las finalidades y principios de las Naciones Unidas.</li><li><mark class=\"m-personalizado\">Peligro para la seguridad interior o exterior de España o para el orden público.</mark></li></ul></div><div class=\"vis-col\"><h5>DENEGACIÓN (arts. 9 y 12)</h5><ul><li>Personas que constituyan, por razones fundadas, un peligro para la seguridad de España.</li><li>Personas que, habiendo sido objeto de una condena firme por delito grave, constituyan una amenaza para la comunidad.</li></ul></div></div></div>"}],"b-10":[{"t":"Art. 10 · Daños graves que dan lugar a la protección subsidiaria","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Art. 10 · Daños graves que dan lugar a la protección subsidiaria</div><div class=\"vis-arbol\"><div class=\"vis-raiz\">Protección <mark class=\"m-personalizado\">subsidiaria</mark>: riesgo real de sufrir</div><div class=\"vis-ramas\"><div class=\"vis-rama\">a) la condena a pena de muerte o el riesgo de su ejecución material;</div><div class=\"vis-rama\">b) la tortura y los tratos inhumanos o degradantes en el país de origen del solicitante;</div><div class=\"vis-rama\">c) las amenazas <mark class=\"m-personalizado\">graves</mark> contra la vida o la integridad de los civiles motivadas por una violencia indiscriminada en situaciones de conflicto <mark class=\"m-personalizado\">internacional o interno</mark>.</div></div></div></div>"}],"b-13":[{"t":"Arts. 13 y 14 · Agentes de persecución y de protección","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>Arts. 13 y 14 · Agentes de persecución y de protección</div><div class=\"vis-comp\" style=\"--n:2\"><div class=\"vis-col\"><h5>AGENTES DE PERSECUCIÓN (art. 13)</h5><ul><li>a) el <mark class=\"m-autoridad\">Estado;</mark></li><li>b) los partidos u organizaciones que controlen el <mark class=\"m-autoridad\">Estado</mark> o una parte considerable de su territorio;</li><li>c) <mark class=\"m-personalizado\">agentes no estatales</mark>, cuando los anteriores, incluidas las organizaciones internacionales, no puedan o no quieran proporcionar protección efectiva.</li></ul></div><div class=\"vis-col\"><h5>AGENTES DE PROTECCIÓN (art. 14)</h5><ul><li>a) el <mark class=\"m-autoridad\">Estado,</mark> o</li><li>b) los partidos u organizaciones, incluidas las organizaciones internacionales, que controlen el <mark class=\"m-autoridad\">Estado</mark> o una parte considerable de su territorio.</li><li>Existe protección si adoptan medidas razonables y efectivas y el solicitante tiene <mark class=\"m-personalizado\">acceso efectivo</mark> a ella.</li></ul></div></div></div>"}],"b-17":[{"t":"Art. 17 · Presentación de la solicitud","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⏱</i>Art. 17 · Presentación de la solicitud</div><div class=\"vis-plazos\"><div class=\"vis-plazo\"><span class=\"n\"><mark class=\"m-personalizado\">Forma</mark></span>Comparecencia personal o, en caso de imposibilidad física o legal, persona que lo represente (ratificación al desaparecer el impedimento).</div><div class=\"vis-plazo\"><span class=\"n\"><mark class=\"m-plazo\">1 mes</mark></span>Sin demora y en todo caso en el plazo máximo de un mes desde la entrada en territorio español o desde los acontecimientos que justifiquen el temor.</div><div class=\"vis-plazo\"><span class=\"n\"><u class=\"m-clave\">Entrada ilegal</u></span><u class=\"m-clave\">No</u> <mark class=\"m-accion\">podrá</mark> ser sancionada si la realiza quien reúne los requisitos para ser beneficiario.</div><div class=\"vis-plazo\"><span class=\"n\"><mark class=\"m-personalizado\">Información</mark></span>Procedimiento; derechos y obligaciones; posibilidad de contactar con el ACNUR y ONG; consecuencias del incumplimiento; derechos y prestaciones sociales.</div><div class=\"vis-plazo\"><span class=\"n\"><mark class=\"m-personalizado\">Entrevista</mark></span>Personal y <mark class=\"m-personalizado\">siempre individualmente</mark>; excepcionalmente, presencia de otros familiares si es imprescindible.</div></div></div>"}],"b-18":[{"t":"Art. 18 · Derechos y obligaciones del solicitante","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>Art. 18 · Derechos y obligaciones del solicitante</div><div class=\"vis-comp\" style=\"--n:2\"><div class=\"vis-col\"><h5>DERECHOS</h5><ul><li>a) ser documentado como solicitante;</li><li>b) asistencia jurídica gratuita e intérprete;</li><li>c) que se comunique su solicitud al ACNUR;</li><li>d) suspensión de cualquier proceso de devolución, expulsión o extradición;</li><li>e) conocer el contenido del expediente en cualquier momento;</li><li>f) atención sanitaria;</li><li>g) prestaciones sociales específicas.</li></ul></div><div class=\"vis-col\"><h5>OBLIGACIONES</h5><ul><li>a) cooperar con las <mark class=\"m-autoridad\">autoridades</mark> españolas;</li><li>b) presentar, lo antes posible, los elementos que fundamenten su solicitud;</li><li>c) impresiones dactilares, fotografías y, en su caso, grabación (previa información);</li><li>d) informar sobre su domicilio y sus cambios;</li><li>e) informar o comparecer ante la <mark class=\"m-autoridad\">autoridad competente</mark> cuando se le requiera.</li></ul></div></div></div>"}],"b-20":[{"t":"Art. 20 · No admisión a trámite (Ministro del Interior, a propuesta de la OAR)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Art. 20 · No admisión a trámite (Ministro del Interior, a propuesta de la OAR)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\">Notificación en <mark class=\"m-plazo\">un mes</mark> desde la presentación; si no, <mark class=\"m-personalizado\">admisión a trámite</mark> y permanencia provisional</div><div class=\"vis-ramas\"><div class=\"vis-rama\">Falta de competencia: a) Reglamento (CE) 343/2003; b) Convenios Internacionales (el <mark class=\"m-autoridad\">Estado</mark> responsable debe aceptarlo explícitamente, con garantías).</div><div class=\"vis-rama\">Falta de requisitos: c) reconocido como refugiado con protección efectiva en un tercer <mark class=\"m-autoridad\">Estado;</mark></div><div class=\"vis-rama\">d) procedente de un tercer país seguro (readmisión y vínculos razonables);</div><div class=\"vis-rama\">e) reiteración de una solicitud denegada o nueva solicitud con otros datos, sin nuevas circunstancias relevantes;</div><div class=\"vis-rama\">f) nacional de un <mark class=\"m-autoridad\">Estado</mark> miembro de la Unión Europea.</div><div class=\"vis-rama\">3. Si se constatan después de la admisión: causa de <mark class=\"m-personalizado\">denegación</mark>.</div></div></div></div>"}],"a-21":[{"t":"Art. 21 · Solicitudes en frontera","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⏱</i>Art. 21 · Solicitudes en frontera</div><div class=\"vis-plazos\"><div class=\"vis-plazo\"><span class=\"n\"><mark class=\"m-plazo\">4 días</mark></span>Inadmisión o denegación por el Ministro del Interior, notificada en el plazo máximo de cuatro días desde la presentación.</div><div class=\"vis-plazo\"><span class=\"n\"><mark class=\"m-plazo\">10 días</mark></span>Ampliación por resolución del Ministro cuando, por causas de exclusión o denegación, el ACNUR lo solicite de manera razonada.</div><div class=\"vis-plazo\"><span class=\"n\"><mark class=\"m-plazo\">2 días</mark></span>Petición de reexamen desde la notificación (suspende los efectos).</div><div class=\"vis-plazo\"><span class=\"n\"><mark class=\"m-plazo\">2 días</mark></span>Resolución del reexamen por el Ministro del Interior desde su presentación.</div><div class=\"vis-plazo\"><span class=\"n\"><mark class=\"m-personalizado\">Silencio</mark></span>Tramitación por el <mark class=\"m-personalizado\">procedimiento ordinario</mark> y autorización de entrada y permanencia provisional.</div></div></div>"}],"b-24":[{"t":"Arts. 23 y 24 · Procedimiento ordinario de protección internacional","h":"<div class=\"vis\"><div class=\"vis-t\"><i>➜</i>Arts. 23 y 24 · Procedimiento ordinario de protección internacional</div><div class=\"vis-flujo\"><div class=\"vis-paso \"><span class=\"et\">Instrucción</span><mark class=\"m-autoridad\">Oficina de Asilo y Refugio</mark> (dependiente del <mark class=\"m-autoridad\">Ministerio</mark> del Interior).</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">Propuesta</span><mark class=\"m-autoridad\">Comisión Interministerial de Asilo y Refugio</mark> (un representante de los departamentos con competencia en política exterior e interior, justicia, inmigración, acogida e igualdad; asiste el representante del ACNUR).</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">Resolución</span><mark class=\"m-autoridad\">Ministro del Interior</mark>: concede o deniega el asilo o la protección subsidiaria.</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\"><mark class=\"m-plazo\">6 meses</mark></span>Sin notificación desde la presentación: <mark class=\"m-accion\">podrá entenderse</mark> <mark class=\"m-personalizado\">desestimada</mark>, sin perjuicio de la obligación de resolver.</div></div></div>"}],"b-33":[{"t":"Art. 33 · Reducción o retirada de los servicios de acogida","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Art. 33 · Reducción o retirada de los servicios de acogida</div><div class=\"vis-arbol\"><div class=\"vis-raiz\">El <mark class=\"m-autoridad\">Ministerio</mark> competente <mark class=\"m-accion\">podrá reducirlos</mark> o retirarlos:</div><div class=\"vis-ramas\"><div class=\"vis-rama\">a) abandono del lugar de residencia asignado sin informar o sin permiso;</div><div class=\"vis-rama\">b) acceso a recursos económicos u ocultación de los mismos, beneficiándose indebidamente;</div><div class=\"vis-rama\">c) resolución de la solicitud notificada (salvo continuidad de programas por circunstancias especiales);</div><div class=\"vis-rama\">d) vulneración de derechos de otros residentes o del personal, o dificultar <mark class=\"m-personalizado\">gravemente</mark> la convivencia;</div><div class=\"vis-rama\">e) finalización del periodo del programa o prestación autorizado.</div><div class=\"vis-rama\">3. El sistema de faltas y sanciones lo establece reglamentariamente el <mark class=\"m-autoridad\">Ministerio</mark> competente.</div></div></div></div>"}],"b-35":[{"t":"Arts. 34 y 35 · Intervención del ACNUR","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⏱</i>Arts. 34 y 35 · Intervención del ACNUR</div><div class=\"vis-plazos\"><div class=\"vis-plazo\"><span class=\"n\"><mark class=\"m-personalizado\">Comunicación</mark></span>Se le comunican las solicitudes; puede informarse, asistir a las audiencias, presentar informes y acceder a los solicitantes (también en frontera, CIE o centros penitenciarios).</div><div class=\"vis-plazo\"><span class=\"n\"><mark class=\"m-personalizado\">CIAR</mark></span>Su representante en España es convocado a las sesiones de la <mark class=\"m-autoridad\">Comisión</mark> Interministerial.</div><div class=\"vis-plazo\"><span class=\"n\"><mark class=\"m-personalizado\">Frontera</mark></span>Informado inmediatamente; puede entrevistarse con los solicitantes; <mark class=\"m-autoridad\">audiencia</mark> antes de resolver.</div><div class=\"vis-plazo\"><span class=\"n\"><mark class=\"m-plazo\">10 días</mark></span>Urgencia y admisiones a trámite con propuesta desfavorable de la OAR: plazo para que informe.</div></div></div>"}],"b-36":[{"t":"Art. 36 · Efectos de la concesión (en todo caso)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Art. 36 · Efectos de la concesión (en todo caso)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\">Concesión del asilo o de la protección subsidiaria</div><div class=\"vis-ramas\"><div class=\"vis-rama\">a) protección contra la devolución;</div><div class=\"vis-rama\">b) información sobre derechos y obligaciones en una lengua comprensible;</div><div class=\"vis-rama\">c) autorización de residencia y trabajo <mark class=\"m-personalizado\">permanente</mark>;</div><div class=\"vis-rama\">d) documentos de identidad y viaje (refugiados; subsidiaria, cuando sea necesario);</div><div class=\"vis-rama\">e) acceso a los servicios <mark class=\"m-personalizado\">públicos</mark> de empleo;</div><div class=\"vis-rama\">f) educación, sanidad, vivienda, servicios sociales, víctimas de violencia de género, seguridad social e integración, en las mismas condiciones que los españoles;</div><div class=\"vis-rama\">g) formación continua u ocupacional, prácticas y reconocimiento de títulos;</div><div class=\"vis-rama\">h) libertad de circulación;</div><div class=\"vis-rama\">i) programas de integración;</div><div class=\"vis-rama\">j) programas de ayuda al retorno voluntario;</div><div class=\"vis-rama\">k) mantenimiento de la unidad familiar.</div></div></div></div>"}],"b-42":[{"t":"Arts. 42 y 43 · Cese","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>Arts. 42 y 43 · Cese</div><div class=\"vis-comp\" style=\"--n:2\"><div class=\"vis-col\"><h5>CESE DEL REFUGIADO (art. 42)</h5><ul><li>a) expresamente así lo soliciten;</li><li>b) acogida de nuevo, voluntariamente, a la protección del país de su nacionalidad;</li><li>c) habiendo perdido su nacionalidad, la hayan recobrado voluntariamente;</li><li>d) nueva nacionalidad con protección de ese país;</li><li>e) establecidos de nuevo, voluntariamente, en el país que abandonaron;</li><li>f) abandono de España y residencia en otro país;</li><li>g) desaparición de las circunstancias (cambio significativo y no temporal);</li><li>h) <mark class=\"m-personalizado\">no teniendo nacionalidad</mark>, pueden regresar a su anterior residencia habitual.</li></ul></div><div class=\"vis-col\"><h5>CESE DE LA SUBSIDIARIA (art. 43)</h5><ul><li>a) se solicite expresamente;</li><li>b) abandono de España y residencia en otro país;</li><li>c) las circunstancias dejen de existir o cambien de tal forma que ya no sea necesaria.</li><li>En ambos: el cese <u class=\"m-clave\">no</u> <mark class=\"m-accion\">impedirá continuar</mark> residiendo conforme a la normativa de extranjería.</li></ul></div></div></div>"}],"b-43":[{"t":"Art. 43 · Cese de la protección subsidiaria (supuestos)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⏱</i>Art. 43 · Cese de la protección subsidiaria (supuestos)</div><div class=\"vis-plazos\"><div class=\"vis-plazo\"><span class=\"n\">a)</span>se solicite expresamente por la persona beneficiaria;</div><div class=\"vis-plazo\"><span class=\"n\">b)</span>la persona beneficiaria haya abandonado el territorio español y fijado su residencia en otro país;</div><div class=\"vis-plazo\"><span class=\"n\">c)</span>las circunstancias que condujeron a su concesión dejen de existir o cambien de tal forma que dicha protección ya no sea necesaria.</div></div></div>"}],"a-44":[{"t":"Art. 44 · Revocación del estatuto de refugiado o de protección subsidiaria","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Art. 44 · Revocación del estatuto de refugiado o de protección subsidiaria</div><div class=\"vis-arbol\"><div class=\"vis-raiz\">Conlleva la aplicación de la normativa de extranjería y, en su caso, el expediente de expulsión; <u class=\"m-clave\">nunca</u> envío a un país con peligro para la vida o la libertad</div><div class=\"vis-ramas\"><div class=\"vis-rama\">a) concurra alguno de los supuestos de exclusión previstos en los artículos 8, 9, 11 y 12;</div><div class=\"vis-rama\">b) haya <mark class=\"m-personalizado\">tergiversado u omitido hechos</mark>, incluido el uso de documentos falsos, decisivos para la concesión;</div><div class=\"vis-rama\">c) constituya un peligro para la seguridad de España o, condenada por delito grave, una amenaza para la comunidad.</div></div></div></div>"}],"b-45":[{"t":"Art. 45 · Procedimiento de cese y revocación","h":"<div class=\"vis\"><div class=\"vis-t\"><i>➜</i>Art. 45 · Procedimiento de cese y revocación</div><div class=\"vis-flujo\"><div class=\"vis-paso \"><span class=\"et\">Inicio</span><mark class=\"m-autoridad\">Oficina de Asilo y Refugio</mark>, de oficio o a instancia de parte (puede archivar si no son fundadas las causas).</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">Garantías</span>Información por escrito, trámite de <mark class=\"m-autoridad\">audiencia,</mark> información precisa y actualizada (ACNUR) y no obtenerla de los responsables de la persecución.</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">CIAR</span><mark class=\"m-autoridad\">Comisión Interministerial</mark>: archiva o eleva propuesta.</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">Resolución</span><mark class=\"m-autoridad\">Ministro del Interior</mark>.</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\"><mark class=\"m-plazo\">6 meses</mark></span>Plazo para notificar; si no, caducidad y archivo de oficio.</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">Recursos</span>Fin de la vía administrativa: reposición potestativa ante el Ministro del Interior y contencioso-administrativo (<u class=\"m-clave\">no</u> alzada).</div></div></div>"}]};